(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zu-sj-prepa-gyneco-j5-sfm"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zu-sj-prepa-gyneco-j5-sfm\",\n \"titre\": \"Préparation D.E (J) · J5 Gynéco-obstétrique SFM\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 50,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J5_Gyneco_SFM_Corrige_explique.pdf\",\n   \"sha256\": \"a85008fe20e77ed6b8adc1407b85a28dceca838bd302963937c9b14b4156a33f\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Gynéco-obstétrique · Prépa D.E J5 (SFM) · J5 et J8 identiques\",\n     \"slug\": \"prepa-gyneco-j5-sfm\",\n     \"pages\": \"\",\n     \"count\": 50,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Gynéco-obstétrique\",\n     \"source\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans le placenta prævia associé à des métrorragies abondantes, la césarienne s'impose en urgence\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Devant un placenta prævia responsable d'hémorragies abondantes mettant en jeu le pronostic vital maternel et/ou fœtal, l'extraction fœtale en urgence par césarienne (associée à la réanimation et à la transfusion sanguine) s'impose sans délai.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Métrorragies du 3e trimestre : conduite à tenir devant un placenta prævia.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__1\",\n       \"num\": \"2\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La Présentation du front est une présentation céphalique où la tête est en hyperextension\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La présentation du front est une présentation céphalique intermédiaire en déflexion partielle (attitude indifférente) ; c'est la présentation de la face qui correspond à une déflexion totale (hyperextension) de la tête fœtale.\\n\\nSource : Cours de Gynéco-Obstétrique — Les présentations céphaliques défléchies (bregma, front, face).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La dessiccation est une complication survenant dans la procidence du cordon 2ème degré\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le refroidissement et la dessiccation de la gelée de Wharton (entraînant un spasme des vaisseaux ombilicaux) surviennent lorsque le cordon est exposé à l'air libre hors des voies génitales, c'est-à-dire dans la procidence du cordon du 3e degré (extériorisée à la vulve), et non au 2e degré (intravaginal).\\n\\nSource : Cours de Gynéco-Obstétrique — Physiopathologie et degrés de la procidence du cordon.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'épreuve du travail est une tentative d'accouchement par voie basse sur un bassin limite\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'épreuve du travail consiste à observer sous surveillance stricte en milieu chirurgical la confrontation céphalo-pelvienne lors d'une tentative d'accouchement par voie basse chez une parturiente présentant un bassin rétréci limite (avec présentation céphalique bien fléchie et fœtus de poids normal), afin d'éviter une césarienne prophylactique abusive.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — L'épreuve du travail (définition et indications).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'autopalpation des seins est un moyen de prévention du cancer du sein qui est pratiqué par un personnel de soins qualifié\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Comme son nom l'indique, l'autopalpation mammaire est un geste d'autosurveillance pratiqué par la femme elle-même (chaque mois après les règles), tandis que la palpation mammaire clinique est réalisée par le professionnel de santé.\\n\\nSource : Cours de Gynéco-Obstétrique — Dépistage et prévention du cancer du sein.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'échographie mammaire est l'examen radiologique à réaliser chez la femme jeune dans le cadre de la prévention du cancer du sein\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Chez la femme jeune (moins de 35-40 ans) dont les seins sont denses et riches en tissu glandulaire, l'échographie mammaire est l'examen d'imagerie de première intention recommandé, la mammographie étant moins performante avant la ménopause.\\n\\nSource : Cours de Gynéco-Obstétrique — Explorations sénologiques et cancer du sein.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le sexe est le premier facteur de risque du cancer du sein\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le sexe féminin est le principal facteur de risque non modifiable du cancer du sein (près de 99 % des cancers du sein surviennent chez la femme, contre moins de 1 % chez l'homme), suivi de l'âge.\\n\\nSource : Cours de Gynéco-Obstétrique — Facteurs de risque du cancer du sein.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La présentation de l'épaule négligée est la complication d'une présentation de l'épaule qui n'a pas été vite prise en charge\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'épaule négligée correspond à l'évolution dramatique d'une présentation transversale méconnue ou non prise en charge à temps : après rupture des membranes et rétraction de l'utérus sur le fœtus, l'épaule s'enclave dans l'excavation avec risque majeur de mort fœtale et de rupture utérine.\\n\\nSource : Cours de Gynéco-Obstétrique — Présentation de l'épaule négligée.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la Présentation du siège complet, on peut percevoir les pieds du fœtus dans l'aire de dilatation\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans la présentation du siège complet (fœtus assis en tailleur avec jambes fléchies sur les cuisses et cuisses fléchies sur le bassin), le toucher vaginal perçoit les fesses accompagnées d'un ou des deux pieds dans l'aire de dilatation cervicale.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Diagnostic clinique de la présentation du siège (p. 68).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'accrochage des mentons au cours d'un accouchement gémellaire peut survenir si J1 est en présentation céphalique et J2 en présentation de siège\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'accrochage des mentons (collision des pôles céphaliques au détroit supérieur) est une complication rare qui survient uniquement lorsque le premier jumeau (J1) est en présentation du siège et le second jumeau (J2) en présentation céphalique (et non l'inverse).\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Dystocies de l'accouchement gémellaire (accrochage des mentons).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__10\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'autopalpation des seins se fait chaque trimestre par la femme elle-même\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'autopalpation mammaire doit être pratiquée par la femme chaque mois (et non chaque trimestre), idéalement quelques jours après la fin des règles (entre le 7e et le 10e jour du cycle) lorsque les seins sont souples et moins congestionnés.\\n\\nSource : Cours de Gynéco-Obstétrique — Prévention et dépistage du cancer du sein (autopalpation). CORRIGÉ EXPLIQUÉ — PRÉPA DE INFAS\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__11\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La manœuvre de Farabœuf est la plus utilisée pour faire le diagnostic de l'engagement\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La recherche du signe de Farabœuf au toucher vaginal (impossibilité d'introduire deux doigts vaginaux entre le pôle céphalique et la concavité sacrée sous S2) est la manœuvre clinique de référence utilisée pour affirmer l'engagement de la présentation du sommet.\\n\\nSource : Cours de Gynéco-Obstétrique — Diagnostic de l'engagement (signe de Farabœuf).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__12\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La première étiologie de l'hémorragie du post partum immédiat est l'atonie utérine\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'atonie (inertie) utérine représente environ 70 à 80 % des cas d'hémorragie du post-partum immédiat (HPPI), devant la rétention placentaire, les traumatismes de la filière génitale et les troubles de la coagulation.\\n\\nSource : Cours de Gynéco-Obstétrique L3 / SONU — Étiologies des hémorragies du post-partum immédiat.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__13\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le cancer du sein est un cancer non hormono-dépendant\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cancer du sein est un cancer fortement hormono-dépendant (sensible aux œstrogènes et à la progestérone dans la majorité des cas), ce qui explique le rôle des facteurs liés à l'imprégnation œstrogénique prolongée (puberté précoce, ménopause tardive, nulliparité) et l'intérêt de l'hormonothérapie.\\n\\nSource : Cours de Gynéco-Obstétrique — Physiopathologie et facteurs de risque du cancer du sein.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__14\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans les grossesses gémellaires dizygotes ; plus la division de l'œuf est tardive, plus elle pourra aboutir à des siamois\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Ce phénomène concerne exclusivement les grossesses gémellaires monozygotes (univitellines, issues de la division d'un seul œuf fécondé) : lorsque cette division survient très tardivement (après le 13e jour post-fécondation), elle est incomplète et donne naissance à des jumeaux conjoints (siamois). Les grossesses dizygotes proviennent de deux œufs distincts sans division.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Embryologie des grossesses gémellaires monozygotes.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__15\",\n       \"num\": \"16\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En cas de dystocies dynamiques, la césarienne s'impose en urgence\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les dystocies dynamiques (anomalies des contractions utérines : hypocinésie ou hypercinésie) relèvent d'abord d'un traitement médical obstétrical adapté (perfusion d'ocytocine en cas d'hypocinésie après vérification de l'absence de disproportion fœto-pelvienne, antispasmodiques/analgésie en cas d'hypercinésie) ; la césarienne n'est indiquée qu'en cas d'échec du traitement médical ou de souffrance fœtale associée.\\n\\nSource : Cours de Gynéco-Obstétrique — Les dystocies dynamiques.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__16\",\n       \"num\": \"17\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le fibrome utérin est une tumeur bénigne\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le fibrome utérin (léiomyome ou myome utérin) est la tumeur bénigne la plus fréquente de l'appareil génital féminin, développée aux dépens des fibres musculaires lisses du myomètre et du tissu conjonctif.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Fibromes utérins et grossesse.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__17\",\n       \"num\": \"18\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La sécrétion du liquide amniotique est essentiellement fœtale et se fait par voie digestive\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La production (sécrétion) du liquide amniotique est essentiellement fœtale mais se fait par voie urinaire (diurèse fœtale) et pulmonaire ; la voie digestive (déglutition fœtale) assure au contraire la résorption (élimination) du liquide amniotique.\\n\\nSource : Cours de Gynéco-Obstétrique — Formation et résorption du liquide amniotique.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__18\",\n       \"num\": \"19\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'HTA au cours de la grossesse est la deuxième cause de mortalité maternelle.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"À l'échelle mondiale et en Afrique subsaharienne, les syndromes hypertensifs gravidiques (prééclampsie et éclampsie) constituent la deuxième cause directe de mortalité maternelle, juste derrière les hémorragies obstétricales graves.\\n\\nSource : Cours de Gynéco-Obstétrique L3 / SONU — Épidémiologie de l'HTA et grossesse.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__19\",\n       \"num\": \"20\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La phase folliculaire est sous la dépendance des œstrogènes\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Durant la première phase du cycle menstruel (phase folliculaire ou pré-ovulatoire), les follicules ovariens en croissance sous l'action de la FSH sécrètent principalement des œstrogènes (œstradiol) qui assurent la prolifération de l'endomètre, tandis que la progestérone prédomine en phase lutéale.\\n\\nSource : Cours de Gynéco-Obstétrique — Physiologie du cycle ovarien et endométrial.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions suivantes, deux (2) situations se retrouvent dans le premier retard : lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Retard d'exécution des soins\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Méconnaissance des signes de danger\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Insuffisance de personnel\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Insuffisance de moyens de référence adéquate\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Faible pouvoir de décision de la femme\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Méconnaissance des signes de danger ; E. Faible pouvoir de décision de la femme\",\n       \"answerLetters\": [\n        \"B\",\n        \"E\"\n       ],\n       \"explanation\": \"Dans le modèle des « trois retards » expliquant la mortalité maternelle, le premier retard (retard à la décision de recourir aux soins) est lié aux facteurs familiaux et communautaires, notamment la méconnaissance des signes de danger et le faible pouvoir décisionnel ou financier de la femme. L'insuffisance de moyens d'évacuation relève du 2e retard, et l'insuffisance de personnel ou le retard de soins du 3e retard.\\n\\nSource : Cours SONU L3 / Gynéco-Obstétrique — Mortalité maternelle et modèle des trois retards.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelle est la complication la plus à craindre en cas de mort fœtale in utero ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Infection\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Rupture utérine\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Trouble de l'hémostase\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Anémie chez la mère\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Trouble de l'hémostase\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"En cas de rétention prolongée d'un fœtus mort in utero (au-delà de 2 à 4 semaines), la complication maternelle la plus redoutable est la survenue de troubles graves de l'hémostase par coagulation intravasculaire disséminée (CIVD) et fibrinolyse due au passage de thromboplastines ovulaires dans la circulation maternelle.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — La mort fœtale in utero (MFIU).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel soin ne doit pas être prodigué après la réfection de l'épisiotomie ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vérifier la symétrie de la suture.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faire des bains de siège.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Surveiller les signes d'infection.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Informer la patiente sur le traitement.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faire des bains de siège.\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Après la réfection d'une épisiotomie, la cicatrice périnéale doit être maintenue propre et bien sèche (toilette vulvaire antiseptique suivie d'un séchage doux) ; les bains de siège sont proscrits car ils favorisent la macération, la désunion des fils et l'infection de la plaie.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — L'épisiotomie et sa réfection (p. 67).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelle manœuvre est réalisée en cas de rétention de la tête dernière lors d'un accouchement de siège ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Manœuvre de Bracht\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Manœuvre de Lovset\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Manœuvre de Mauriceau\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Attitude de Vermelin\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Manœuvre de Mauriceau\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La manœuvre de Mauriceau est la manœuvre spécifique indiquée pour fléchir, orienter et extraire la tête dernière retenue dans l'excavation pelvienne lors de l'accouchement en présentation du siège.\\n\\nSource : Cours de Gynéco-Obstétrique L3 / SONU — Manœuvres obstétricales dans l'accouchement du siège.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Laquelle de ces présentations est considérée comme hautement dystocique ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Présentation du sommet\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Présentation du bregma\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Présentation du front\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Présentation du siège\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Présentation du front\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La présentation du front (présentation céphalique intermédiaire en déflexion partielle fixée) est la plus dystocique des présentations céphaliques car elle présente son plus grand diamètre (syncipito-mentonnier de 13,5 cm), rendant l'accouchement par voie basse impossible à terme et imposant la césarienne.\\n\\nSource : Cours de Gynéco-Obstétrique — Les présentations dystociques (présentation du front).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel est le degré de procidence où le cordon est extériorisé à la vulve ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Degré I\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Degré II\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Degré III\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Degré IV\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Degré III\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Dans la classification anatomo-clinique de la procidence du cordon : au degré I, le cordon est perçu dans l'aire de dilatation cervicale sans descendre dans le vagin ; au degré II, il descend dans le vagin sans atteindre la vulve ; au degré III, l'anse funiculaire s'extériorise hors de la vulve.\\n\\nSource : Cours de Gynéco-Obstétrique — La procidence du cordon ombilical.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"A quelle phase du travail peut survenir une dilatation stationnaire ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Phase de latence uniquement\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Phase active uniquement\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Les deux phases\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Phase de délivrance\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Les deux phases\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Une anomalie de progression de la dilatation cervicale (arrêt ou stagnation de la dilatation sur deux examens successifs) peut s'observer aussi bien durant la phase de latence (phase de latence prolongée) que durant la phase active du travail (dilatation stationnaire proprement dite).\\n\\nSource : Cours de Gynéco-Obstétrique / SONU — Surveillance du travail et anomalies de la dilatation.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelle est l'origine principale du liquide amniotique pendant la grossesse ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Exsudation à travers les membranes\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Urines du fœtus\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Sueur de la mère\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Transfusion sanguine\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Urines du fœtus\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"À partir de la deuxième moitié de la grossesse, le liquide amniotique est produit principalement par la diurèse fœtale (urines du fœtus) et les sécrétions broncho-pulmonaires fœtales, tandis que sa résorption est assurée par la déglutition fœtale.\\n\\nSource : Cours de Gynéco-Obstétrique — Physiologie des annexes fœtales (liquide amniotique).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel est l'un des objectifs du traitement de la grossesse extra-utérine ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Augmenter le taux de BHCG\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Préserver la fertilité\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Accélérer la croissance du fœtus\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Permettre la migration de l'œuf dans l'utérus\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Préserver la fertilité\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Outre le sauvetage maternel par suppression de la grossesse ectopique et contrôle de l'hémorragie, l'un des objectifs essentiels de la prise en charge (traitement médical par méthotrexate ou chirurgie conservatrice par salpingotomie) est de préserver autant que possible la fertilité ultérieure de la patiente.\\n\\nSource : Cours de Gynéco-Obstétrique — La grossesse extra-utérine (GEU).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Vous recevez dans votre centre de santé urbain une primipare dilatée à 3 cm avec un fœtus présentant une souffrance fœtale aiguë, deux attitudes sont à réaliser : lesquelles ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hâter l'accouchement par voie basse par une perfusion d'ocytocique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Administrer le sérum glucosé hypertonique à 10%\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Faire une extraction instrumentale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Référer en urgence la parturiente vers un centre obstétrico-chirurgical\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Il n'est pas nécessaire de faire une réanimation néonatale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Administrer le sérum glucosé hypertonique à 10% ; D. Référer en urgence la parturiente vers un centre obstétrico-chirurgical\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Dans un centre de santé urbain (structure SONU-B dépourvue de bloc opératoire) devant une souffrance fœtale aiguë à 3 cm de dilatation, la conduite d'urgence associe les mesures de réanimation fœtale in utero (décubitus latéral gauche, arrêt des ocytociques, oxygénothérapie et perfusion de sérum glucosé hypertonique à 10 %) à l'évacuation sanitaire urgente vers un centre obstétrico-chirurgical (SONU-C) pour césarienne de sauvetage.\\n\\nSource : Cours SONU L3 / Gynéco-Obstétrique — Conduite à tenir devant une souffrance fœtale aiguë (SFA).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Deux propositions sont exactes concernant les grossesses gémellaires bi-ovulaires : lesquelles ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Elle est toujours bi choriale bi amniotique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Les fœtus sont toujours de même sexe\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Ce sont des faux jumeaux\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les fœtus sont toujours de sexe différent\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Elle peut donner naissance à des siamois\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Elle est toujours bi choriale bi amniotique ; C. Ce sont des faux jumeaux\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Les grossesses gémellaires biovulaires (dizygotes) résultent de la fécondation de deux ovules distincts par deux spermatozoïdes différents : ce sont donc de « faux jumeaux » (de même sexe ou de sexes différents) et chaque œuf développe son propre placenta et sa propre poche, les rendant toujours bichoriales biamniotiques.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Les grossesses gémellaires.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__31\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Concernant le cordon ombilical : deux assertions sont fausses : lesquelles ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Il contient 3 vaisseaux\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Il contient un nerf\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Il contient deux artères et une veine\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Il contient deux veines et une artère\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Il mesure en moyenne 60 cm\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Il contient un nerf ; D. Il contient deux veines et une artère\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Anatomiquement, le cordon ombilical est totalement dépourvu de nerfs (il est insensible) et renferme 3 vaisseaux entourés de la gelée de Wharton : deux artères ombilicales et une seule veine ombilicale (et non deux veines et une artère), pour une longueur moyenne de 50 à 60 cm.\\n\\nSource : Cours de Gynéco-Obstétrique — Étude du cordon ombilical.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__32\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le phénomène Transfuseur/Transfusé se retrouve dans une des situations suivantes : laquelle ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Chez des jumeaux de sexes différents\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Dans la grossesse gémellaire bi ovulaire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Dans la grossesse gémellaire bi choriale bi amniotique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Dans les grossesses gémellaires mono choriale bi amniotique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Dans les grossesses gémellaires mono choriale bi amniotique\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Le syndrome transfuseur-transfusé (STT) est une complication spécifique des grossesses gémellaires monochoriales (placenta unique partagé par les deux fœtus, le plus souvent monochoriales biamniotiques), liée à un déséquilibre hémodynamique à travers des anastomoses vasculaires placentaires artério-veineuses profondes.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Complications des grossesses gémellaires.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__33\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Laquelle de ces propositions est exacte, concernant le placenta\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le cordon ombilical s'insère sur la face maternelle\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Il pèse en moyenne 1/6 du poids du fœtus à terme\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La face fœtale est charnue et contient des cotylédons\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Il permet de maintenir la grossesse dès la fécondation de l'œuf\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Il pèse en moyenne 1/6 du poids du fœtus à terme\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"À terme, le placenta humain pèse environ 500 à 600 g, soit en moyenne 1/6 du poids du fœtus. C'est la face maternelle qui porte les cotylédons, le cordon s'insère sur la face fœtale, et le maintien hormonal du début de grossesse est assuré par le corps jaune gravidique avant le relais placentaire.\\n\\nSource : Cours de Gynéco-Obstétrique — Étude du placenta.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__34\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'une des propositions suivantes ne se retrouve pas dans la présentation de l'épaule négligée : laquelle ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le fœtus est le plus souvent vivant\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Elle fait partie des présentations transversales\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"On retrouve une procidence du bras\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Infection ovulaire probable\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Le fœtus est le plus souvent vivant\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La présentation de l'épaule négligée est une urgence obstétricale dramatique survenant après rupture prolongée des membranes et rétraction utérine autour du fœtus enclavé (avec procidence du bras et infection ovulaire quasi constante) : en raison de la compression funiculaire et de l'hypertonie utérine, le fœtus est le plus souvent déjà mort in utero.\\n\\nSource : Cours de Gynéco-Obstétrique — La présentation transversale (épaule négligée).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__35\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les présentations suivantes, l'une a pour diamètre d'engagement le diamètre occipito-frontal : laquelle ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La Présentation du front\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La Présentation du sommet\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La Présentation du bregma\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La Présentation de la face\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. La Présentation du bregma\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Dans la présentation céphalique légèrement défléchie du bregma (grande fontanelle au centre), la tête présente au détroit supérieur son diamètre occipito-frontal mesurant 11,5 à 12 cm (contre 9,5 cm sousoccipito-bregmatique pour le sommet, 13,5 cm syncipito-mentonnier pour le front et 9,5 cm sous-mentobregmatique pour la face).\\n\\nSource : Cours de Gynéco-Obstétrique — Diamètres d'engagement des présentations céphaliques.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__36\",\n       \"num\": \"37\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"A quel diagnostic pensez-vous ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"HTA gravidique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Pré-éclampsie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"HTA chronique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Pré-éclampsie surajoutée\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Pré-éclampsie surajoutée\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Chez une gestante présentant une hypertension artérielle chronique connue avant la grossesse (ou avant 20 SA), l'apparition après 20 SA (ici à 33 SA) d'une protéinurie significative et de signes fonctionnels de gravité (céphalées en casque, flou visuel) définit une pré-éclampsie surajoutée.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Syndromes vasculo-rénaux : classification de l'HTA pendant la grossesse.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__37\",\n       \"num\": \"38\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"15 minutes après son admission, elle présente une crise convulsive. Il s'agit d'une\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Pré-éclampsie sévère avec signe d'éclampsisme\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Crise hystérie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Crise d'éclampsie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Crise d'épilepsie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Crise d'éclampsie\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Une crise convulsive chez une femme en pré-éclampsie est une éclampsie. Toute convulsion en cours de grossesse est traitée comme une éclampsie jusqu'à preuve du contraire.\\n\\nSource : Cours de soins obstétricaux 2e année SF, « HTA / éclampsie et grossesse »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__38\",\n       \"num\": \"39\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"N'ayant jamais assisté à un tel événement, vous contactez votre médecin référant qui vous donne des instructions. Parmi ces instructions, vous décidez de suivre deux, lesquelles ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Appeler à l'aide\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Mettre une compresse dans la bouche de la patiente\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La mettre en position latérale de sécurité\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'attacher au lit\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Administrer 5 cc de valium en IM\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Appeler à l'aide ; C. La mettre en position latérale de sécurité\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Devant une crise d'éclampsie en cours, les premiers gestes d'urgence visent à protéger la patiente et mobiliser l'équipe : appeler immédiatement à l'aide et installer la patiente en position latérale de sécurité (PLS) gauche pour éviter l'inhalation et la compression aorto-cave. Il ne faut ni l'attacher ni introduire d'objet dans sa bouche, et le sulfate de magnésium est préféré au diazépam (Valium).\\n\\nSource : Cours SONU L3 — Conduite à tenir devant une crise d'éclampsie.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__39\",\n       \"num\": \"40\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"Après avoir validé votre décision, il vous demande de faire un traitement pré-transfert. Quelle molécule allez-vous utiliser en première intention ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Valium\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Célestène\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Sulfate de magnésium\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Gardénal\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Sulfate de magnésium\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le sulfate de magnésium (MgSO4) est l'anticonvulsivant de référence recommandé en première intention par l'OMS et les protocoles SONU pour arrêter les convulsions et prévenir la récidive des crises d'éclampsie.\\n\\nSource : Cours SONU L3 / Gynéco-Obstétrique — Protocole au sulfate de magnésium.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__40\",\n       \"num\": \"41\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"Quelle est la dose de charge à administrer en intramusculaire ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"4 grammes\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"5 grammes\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"10 grammes\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"14 grammes\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 10 grammes\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Selon le protocole standard de Pritchard enseigné dans les modules SONU, la dose de charge totale de 14 g de sulfate de magnésium associe 4 g en intraveineuse lente (en 5-15 min) et 10 g par voie intramusculaire profonde (soit 5 g dans chaque fesse avec 1 ml de lidocaïne à 2 %).\\n\\nSource : Cours SONU L3 — Schéma d'administration du sulfate de magnésium (protocole de Pritchard).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__41\",\n       \"num\": \"42\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"En attendant l'ambulance pour son transfert, vous décidez de surveiller la patiente. Quels sont les deux paramètres les plus importants de cette surveillance ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La fréquence cardiaque\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La température\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La fréquence respiratoire\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'état de conscience\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"La tension artérielle\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. La fréquence respiratoire ; E. La tension artérielle\",\n       \"answerLetters\": [\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"La surveillance immédiate d'une patiente éclamptique sous sulfate de magnésium repose prioritairement sur le contrôle de la tension artérielle (risque d' poussée hypertensive et d'AVC) et de la fréquence respiratoire (qui doit rester ≥ 16 cycles/min pour dépister précocement un surdosage en magnésium, complétée par la diurèse et les réflexes ostéo-tendineux).\\n\\nSource : Cours SONU L3 — Surveillance d'une patiente sous sulfate de magnésium.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__42\",\n       \"num\": \"43\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"La patiente est admise 3 heures de temps après à l'Hôpital général de référence. D'après vous quelle serait la conduite à tenir dans le centre de référence ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hospitaliser la patiente pour une meilleure surveillance de la grossesse\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Préconiser un déclenchement en vue d'un accouchement par voie basse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Réaliser une césarienne en urgence\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Faire une maturation pulmonaire et prévoir l'intervention à la 36 SA\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Réaliser une césarienne en urgence\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'évacuation utérine est le seul traitement curatif de l'éclampsie ; après une crise d'éclampsie chez une femme stabilisée au centre de référence, l'accouchement doit être obtenu rapidement ; la correction nationale de la Prépa DE (les J) retient la césarienne en urgence (on n'attend pas 36 SA).\\n\\nSource : ECLAMPSIE (diaporama du projet), « Conclusion » ; Cours de soins obstétricaux 2e année SF, « CAT devant une éclampsie »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__43\",\n       \"num\": \"44\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"Elle donne naissance à un prématuré pesant 1300 grammes, APGAR 5,6 : il s'agit d'un(e)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Bon état initial\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"État de mort apparente\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Dépression respiratoire immédiate\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Dépression respiratoire immédiate\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Un score d'Apgar de 5-6 traduit un nouveau-né en difficulté sans mort apparente : dépression respiratoire (état intermédiaire). Le cours indique de réanimer immédiatement si l'Apgar est ≤ 7. (explication partiellement hors cours du projet)\\n\\nSource : SONU Licence 2 SFM (2025-2026), « Soins à l'accouchée et au nouveau-né », Appréciation du score d'Apgar\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__44\",\n       \"num\": \"45\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"Quels seront les deux gestes à réaliser dans ce cas\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Désobstruction des voies aériennes\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Massage cardiaque externe\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Administrer d'adrénaline\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Ventilation externe\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Intubation trachéale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Désobstruction des voies aériennes ; D. Ventilation externe\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\"\n       ],\n       \"explanation\": \"Devant un nouveau-né présentant une dépression respiratoire modérée (Apgar 5-6), les gestes prioritaires de réanimation néonatale de base consistent à sécher et réchauffer l'enfant, assurer la désobstruction des voies aériennes supérieures puis débuter la ventilation externe au ballon et au masque.\\n\\nSource : Cours SONU / Pédiatrie — Algorithme de réanimation du nouveau-né.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__45\",\n       \"num\": \"46\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"Lors de la surveillance, Mme X demande au Maïeuticien en salle de réveil de surélever la tête du lit car elle arrive difficilement à respirer. Elle présente une toux avec des crachats mêlés de sang. A quel diagnostic pensez-vous ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une tuberculose pulmonaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une crise d'asthme\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un œdème aigu du poumon\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une embolie pulmonaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Un œdème aigu du poumon\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'apparition brutale d'une dyspnée avec orthopnée (besoin d'être assise), toux et expectoration mousseuse rosée ou striée de sang (crachats hémoptoïques) chez une patiente éclamptique en post-opératoire est typique d'un œdème aigu du poumon (OAP), complication classique de la pré-éclampsie/éclampsie et des remplissages vasculaires excessifs.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Complications maternelles de la pré-éclampsie et de l'éclampsie (OAP).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__46\",\n       \"num\": \"47\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"Quel geste important aurait dû être réalisé par la sage-femme ayant reçu la patiente dans le centre de santé urbain et qui aurait pu prévenir cette complication\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La prise d'une bonne voie veineuse avant son évacuation\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La surveillance de la tension artérielle, de la fréquence respiratoire et du pouls régulièrement\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La mise en place d'une sonde urinaire\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La mise en place d'une canule de GUEDEL dans la bouche\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. La surveillance de la tension artérielle, de la fréquence respiratoire et du pouls régulièrement\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La surveillance étroite et régulière des constantes vitales (tension artérielle, fréquence respiratoire, pouls et bilan hydrique) permet de détecter précocement les poussées hypertensives et la surcharge pulmonaire afin d'adapter les apports liquidiens et prévenir l'OAP.\\n\\nSource : Cours SONU L3 — Surveillance clinique de la pré-éclampsie sévère et de l'éclampsie.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__47\",\n       \"num\": \"48\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"Le protocole mis en place permet de stabiliser la patiente. 1 heure après, l'aide-soignante voulant nettoyer la patiente constate que tout les draps sont imbibés de sang et vous alerte ; votre examen retrouve une voie non perméable, TA : 08/06 cmHg et un pouls à 112 BPM. Il s'agit probablement d'une hémorragie du post-partum immédiat par\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rétention placentaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Coagulopathie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Déchirure du col\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Atonie utérine\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Atonie utérine\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Draps imbibés de sang, hypotension (8/6) et tachycardie (112) dans le post-partum immédiat : HPPI avec choc. La première cause à évoquer est l'atonie utérine.\\n\\nSource : Gynécologie-Obstétrique L3, « CAT devant une HPP » ; SONU L3 (2024-2025), « Prise en charge du choc »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__48\",\n       \"num\": \"49\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"Quelle serait votre conduite à tenir en urgence\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'ablation de l'utérus\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Perméabiliser de la voie veineuse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Faire une délivrance artificielle\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Mettre un tamponnement intra-utérin par ballonnet (UBT)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Perméabiliser de la voie veineuse\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Devant un état de choc hémorragique (TA 08/06 cmHg, pouls 112 bpm) avec une voie veineuse obstruée (« non perméable »), le tout premier geste d'urgence vitale consiste à rétablir/perméabiliser immédiatement l'abord veineux afin de démarrer le remplissage vasculaire et l'administration des utérotoniques. L'utérus est déjà vide (post-césarienne), et le ballonnet ou l'hystérectomie n'interviennent qu'en cas d'échec du traitement médical de première ligne.\\n\\nSource : Cours SONU L3 — Prise en charge d'urgence de l'hémorragie du post-partum.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j5-sfm__49\",\n       \"num\": \"50\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE : Vous êtes une Sage-femme/Maïeuticien nouvellement affecté dans un centre de santé urbain. Vous consultez Mme X, âgée de 24 ans, G3P1, hypertendue connue, lors de sa première consultation à 33 semaines d'aménorrhée. L'interrogatoire révèle des céphalées en casque associées à un flou visuel. À l'admission, les résultats montrent une tension artérielle à 15/08 cmHg, protéinurie ++.\",\n       \"text\": \"Tout se passe bien et après 5 jours d'hospitalisation vous prévoyez sa sortie après un counselling en planification familiale. Quelle méthode peut-elle utiliser avant sa sortie de l'hôpital ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le dispositif intra-utérin\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Les injectables à seul progestatif\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'implant\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les injectables combinés\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. L'implant\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"À J5 du post-partum, après pré-éclampsie et chez une femme qui allaite : les méthodes œstroprogestatives (injectables combinés) sont contre-indiquées (catégorie 4), le DIU est déconseillé entre 48 h et 4 semaines (catégorie 3), les injectables progestatifs sont en catégorie 3 avant 6 semaines d'allaitement. L'implant (catégorie 2) peut être posé avant la sortie.\\n\\nSource : Cours SR/PF L2 (Document SSR), chap. 17, « Critères d'éligibilité appliqués au post-partum »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Gynéco-obstétrique SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Gyneco_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
